def maximumValueSum(board):
    m, n = len(board), len(board[0])

    # 1. keep the 3 largest cells of every row
    cells = []
    for i in range(m):
        top = sorted(range(n), key=lambda j: board[i][j], reverse=True)[:3]
        for j in top:
            cells.append((board[i][j], i, j))

    # 2. among those, keep the 3 largest cells of every column
    by_col = {}
    for v, i, j in cells:
        by_col.setdefault(j, []).append((v, i, j))
    cand = []
    for lst in by_col.values():
        lst.sort(reverse=True)
        cand.extend(lst[:3])
    cand.sort(reverse=True)  # by value, descending

    # 3. choose the first rook a; only the best few non-attacking cells matter
    best = float('-inf')
    for va, ra, ca in cand:
        pool = []
        for v, r, c in cand:
            if r != ra and c != ca:
                pool.append((v, r, c))
                if len(pool) == 8:
                    break
        for x in range(len(pool)):
            for y in range(x + 1, len(pool)):
                if pool[x][1] != pool[y][1] and pool[x][2] != pool[y][2]:
                    total = va + pool[x][0] + pool[y][0]
                    if total > best:
                        best = total
    return best
